// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    // allow this contract (deployer/owner of c) to receive ETH via transfer
    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);

        // deposit through the (payable) fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertTrue(address(c).balance == amount);

        // owner (this contract) drains everything
        c.withdrawAll();

        // RULE: withdrawAll must leave the contract with exactly 0 wei.
        assertTrue(address(c).balance == 0);
    }
}
